<script setup lang="ts">
/**
 * UserMenu (R5.1) — the shell account affordance. An avatar button opens a
 * focus-trapped popover: when signed in, the user's name + a Settings link +
 * Sign out (`useAuthStore.logout` then route to login); when signed out, a
 * Sign in link. Links are `routerBase`-aware (config). Esc / click-outside close.
 */
import { computed, inject, onBeforeUnmount, ref, watch } from 'vue';
import { useRouter } from 'vue-router';
import Icon from '../components/Icon.vue';
import { useFocusTrap } from '../components/ui/useFocusTrap';
import { useAuthStore } from '../stores/useAuthStore';
import { useProfileStore } from '../stores/useProfileStore';
import { useMessages } from '../composables/useMessages';
import { useImageSrc } from '../composables/useImageSrc';
import { profilesFeatureEnabled } from './profilesFeature';
import type { PhlixAppConfig } from './types';

const auth = useAuthStore();
const profiles = useProfileStore();
const router = useRouter();
const config = inject<PhlixAppConfig | null>('phlixConfig', null);
const homePath = computed(() => config?.routerBase ?? '/app');
/** S462: same flag PhlixApp gates the Who's-watching mount on — when profiles
 *  are off for this app, the switch/manage arms must not render at all. */
const profilesEnabled = computed(() => profilesFeatureEnabled(config));
const { t } = useMessages();
/** S241: avatar_url is a ROOT-RELATIVE `/api/v1/users/{id}/avatar`; resolve it
 *  against the media base so it loads over the relay proxy on the hub. */
const { imgSrc } = useImageSrc();

const open = ref(false);
const rootEl = ref<HTMLElement | null>(null);
const panelEl = ref<HTMLElement | null>(null);

const displayName = computed(
  () => auth.user?.username || auth.user?.name || auth.user?.email || t('shell.account'),
);
const avatarError = ref(false);

function getInitials(name: string): string {
  const parts = name.trim().split(/\s+/).filter(Boolean);
  if (parts.length === 0) return '?';
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
  return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
}

// Reset error flag when avatar_url changes so the new URL is tried
watch(
  () => auth.user?.avatar_url,
  () => { avatarError.value = false; },
);

function close(): void {
  open.value = false;
}
function go(path: string): void {
  close();
  void router.push(path);
}
function signOut(): void {
  close();
  auth.logout();
  void router.push(`${homePath.value}/login`);
}
/** Re-arms the Who's-watching gate (S82). With one profile the gate's own
 *  condition keeps it closed — nothing to switch to, nothing shown. */
function switchProfile(): void {
  close();
  profiles.openGate();
}

useFocusTrap(panelEl, open, {
  lockScroll: false,
  onEscape: () => {
    close();
    return true;
  },
});

// L2: `role="menu"` promises Menu-pattern keyboard semantics (same contract
// ui/Menu.vue implements): ArrowDown/Up walk the items with wrap-around,
// Home/End jump to the edges. Items are real <button>s, so Enter/Space activate
// natively once focused; Tab/Esc stay the trap's business.
function menuItems(): HTMLElement[] {
  return Array.from(
    panelEl.value?.querySelectorAll<HTMLElement>('[role="menuitem"]:not([disabled])') ?? [],
  );
}

function focusItemAt(items: HTMLElement[], index: number): void {
  const wrapped = (index + items.length) % items.length;
  items[wrapped]?.focus();
}

function onPanelKeydown(e: KeyboardEvent): void {
  const items = menuItems();
  if (items.length === 0) return;
  const current = items.indexOf(document.activeElement as HTMLElement);
  switch (e.key) {
    case 'ArrowDown':
      e.preventDefault();
      focusItemAt(items, current + 1);
      break;
    case 'ArrowUp':
      e.preventDefault();
      // Focus outside the item set (panel itself): walk to the LAST item.
      focusItemAt(items, current === -1 ? -1 : current - 1);
      break;
    case 'Home':
      e.preventDefault();
      items[0]?.focus();
      break;
    case 'End':
      e.preventDefault();
      items[items.length - 1]?.focus();
      break;
  }
}

function onDocPointer(e: PointerEvent): void {
  if (rootEl.value && !rootEl.value.contains(e.target as Node)) close();
}
watch(open, (v) => {
  if (typeof document === 'undefined') return;
  if (v) document.addEventListener('pointerdown', onDocPointer, true);
  else document.removeEventListener('pointerdown', onDocPointer, true);
});
onBeforeUnmount(() => {
  if (typeof document !== 'undefined') document.removeEventListener('pointerdown', onDocPointer, true);
});
</script>

<template>
  <div ref="rootEl" class="usermenu">
    <button
      type="button"
      class="usermenu__trigger"
      :aria-label="auth.isLoggedIn ? t('shell.accountNamed', { name: displayName }) : t('shell.account')"
      aria-haspopup="menu"
      :aria-expanded="open"
      @click="open = !open"
    >
      <span v-if="auth.isLoggedIn" class="usermenu__avatar">
        <img
          v-if="auth.user?.avatar_url && !avatarError"
          :src="imgSrc(auth.user.avatar_url)"
          :alt="displayName"
          class="usermenu__avatar-img"
          @error="avatarError = true"
        />
        <span v-else class="usermenu__avatar-initials">{{ getInitials(displayName) }}</span>
      </span>
      <Icon v-else name="user" />
    </button>

    <div
      v-if="open"
      ref="panelEl"
      class="usermenu__panel"
      role="menu"
      :aria-label="t('shell.account')"
      tabindex="-1"
      @keydown="onPanelKeydown"
    >
      <template v-if="auth.isLoggedIn">
        <div class="usermenu__head">
          <span class="usermenu__avatar usermenu__avatar--lg">
            <img
              v-if="auth.user?.avatar_url && !avatarError"
              :src="imgSrc(auth.user.avatar_url)"
              :alt="displayName"
              class="usermenu__avatar-img"
              @error="avatarError = true"
            />
            <span v-else class="usermenu__avatar-initials">{{ getInitials(displayName) }}</span>
          </span>
          <span class="usermenu__name">{{ displayName }}</span>
        </div>
        <button type="button" class="usermenu__item" role="menuitem" @click="go(`${homePath}/history`)">
          <Icon name="film" /> {{ t('shell.watchHistory') }}
        </button>
        <!-- S82 profile entries, S462-gated on the profiles feature flag. "Switch
             Profile" re-arms the Who's-watching gate (its own >1-profile condition
             decides whether it actually shows); "Manage Profiles" routes to the
             self-service management page. With profiles off for this app the arms
             must not render at all — no dead entry into a gate that can never open. -->
        <template v-if="profilesEnabled">
          <button type="button" class="usermenu__item" role="menuitem" data-testid="usermenu-switch-profile"
            @click="switchProfile">
            <Icon name="users" /> {{ t('shell.switchProfile') }}
          </button>
          <button type="button" class="usermenu__item" role="menuitem" data-testid="usermenu-manage-profiles"
            @click="go(`${homePath}/profiles`)">
            <Icon name="settings" /> {{ t('shell.manageProfiles') }}
          </button>
        </template>
        <button type="button" class="usermenu__item" role="menuitem" @click="go(`${homePath}/settings`)">
          <Icon name="settings" /> {{ t('shell.settings') }}
        </button>
        <button type="button" class="usermenu__item" role="menuitem" @click="signOut">
          <Icon name="log-out" /> {{ t('shell.signOut') }}
        </button>
      </template>
      <template v-else>
        <button type="button" class="usermenu__item" role="menuitem" @click="go(`${homePath}/login`)">
          <Icon name="user" /> {{ t('shell.signIn') }}
        </button>
      </template>
    </div>
  </div>
</template>

